#!/usr/bin/env node
/*
 * generate-guide-class — docs/agents/building-apps.md as an ABAP class, so the
 * guide to building an app is in every system abap2UI5 is installed in.
 *
 * abapGit installs src/ and nothing else, so the guide an agent builds apps
 * from never reached a system - and the assistants that work IN the system
 * (they read its custom code, not this repository) found the framework's
 * code but not how to use it, and guessed. In the system, beside the code it
 * describes, the guide is always the one for the release installed: the same
 * reason the browser playground builds its prompt from the guide of the
 * commit its runtime is transpiled from.
 *
 *   src/01/05/z2ui5_cl_ui5_llm_guide.clas.abap   get( ) answers the guide
 *   src/01/05/z2ui5_cl_ui5_llm_guide.clas.xml
 *
 * Apps reach it through the contract, z2ui5_cl_ui5_llm=>guide( ) - this
 * class is the engine's and may move. It sits beside the language model
 * providers because the guide is what a model is given to build an app.
 *
 * The text is the guide's, line for line, with two changes the ABAP side
 * forces:
 *
 *   - 7-bit ASCII (abaplint's 7bit_ascii, AGENTS.md rule 14): the characters
 *     in TRANSLITERATE are written in ASCII. Any other character outside it
 *     FAILS with its line - a new one needs a spelling decided here, not a
 *     byte that breaks the import.
 *   - 255 characters per ABAP line: a long line of the guide is cut into
 *     several literals joined without a newline, so get( ) still answers it
 *     as one line. Trailing whitespace is dropped (the abapGit format gate).
 *
 * Every 400 lines the chain is closed and a new statement starts, as
 * tools/app2abap/trans2abap.js does - ABAP caps the length of one chained
 * expression.
 *
 *   node .github/scripts/generate-guide-class.mjs          write the class (npm run guide-class)
 *   node .github/scripts/generate-guide-class.mjs --check  fail if stale   (npm run check:guide-class)
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const CHECK = process.argv.includes("--check");

const SOURCE = "docs/agents/building-apps.md";
const CLASS = "z2ui5_cl_ui5_llm_guide";
const ABAP = `src/01/05/${CLASS}.clas.abap`;
const XML = `src/01/05/${CLASS}.clas.xml`;

const TRANSLITERATE = [
  ["—", "-"],
  ["–", "-"],
  ["…", "..."],
  ["→", "->"],
  ["§", "section "],
];

// Characters of the guide per literal: a doubled backtick still fits, with
// the indentation and `&& |\n| &&` around it, under 255.
const PIECE = 110;
const STATEMENT_LINES = 400;
const INDENT = "             ";

function ascii(text) {
  let out = text;
  for (const [from, to] of TRANSLITERATE) out = out.split(from).join(to);
  out.split("\n").forEach((line, i) => {
    // The range IS ASCII, control characters included: this is the rule.
    // eslint-disable-next-line no-control-regex
    const bad = line.match(/[^\x00-\x7F]/);
    if (bad) {
      throw new Error(
        `${SOURCE} line ${i + 1}: ${JSON.stringify(bad[0])} (U+${bad[0].codePointAt(0).toString(16).toUpperCase()}) ` +
          "has no ASCII spelling yet - add one to TRANSLITERATE in .github/scripts/generate-guide-class.mjs",
      );
    }
  });
  return out;
}

const literal = (s) => `\`${s.replace(/`/g, "``")}\``;

// One line of the guide as ABAP lines: its pieces joined with &&, the last
// one followed by the newline.
function abapLines(line) {
  const text = line.replace(/\s+$/, "");
  if (text === "") return [`${INDENT}|\\n| &&`];
  const pieces = [];
  for (let i = 0; i < text.length; i += PIECE) pieces.push(text.slice(i, i + PIECE));
  return pieces.map((p, i) => `${INDENT}${literal(p)} &&${i === pieces.length - 1 ? " |\\n| &&" : ""}`);
}

export function guideClass(markdown) {
  const lines = ascii(markdown.replace(/\r\n/g, "\n")).replace(/\n$/, "").split("\n");
  const body = [];
  lines.forEach((line, i) => {
    body.push(...abapLines(line));
    if ((i + 1) % STATEMENT_LINES === 0 && i + 1 < lines.length) {
      body[body.length - 1] = body[body.length - 1].replace(/\s*&&$/, ".");
      body.push("    result = result &&");
    }
  });
  return `* =====================================================================
* GENERATED FILE - DO NOT EDIT
* Source: ${SOURCE}
* The guide to building an app with abap2UI5, for the developer and for
* the AI assistant working in this system - the guide of exactly the
* release installed here. Apps call z2ui5_cl_ui5_llm=>guide( ).
* Generated by .github/scripts/generate-guide-class.mjs: change the
* source above and run 'npm run guide-class'; 'npm run check:guide-class'
* fails any edit made here by hand.
* =====================================================================
CLASS ${CLASS} DEFINITION
  PUBLIC
  FINAL
  CREATE PUBLIC.

  PUBLIC SECTION.

    CLASS-METHODS get
      RETURNING
        VALUE(result) TYPE string.

  PROTECTED SECTION.
  PRIVATE SECTION.
ENDCLASS.


CLASS ${CLASS} IMPLEMENTATION.

  METHOD get.

    result =
${body.join("\n")}
             \`\`.

  ENDMETHOD.

ENDCLASS.
`;
}

const XML_TEXT = `﻿<?xml version="1.0" encoding="utf-8"?>
<abapGit version="v1.0.0" serializer="LCL_OBJECT_CLAS" serializer_version="v1.0.0">
 <asx:abap xmlns:asx="http://www.sap.com/abapxml" version="1.0">
  <asx:values>
   <VSEOCLASS>
    <CLSNAME>${CLASS.toUpperCase()}</CLSNAME>
    <LANGU>E</LANGU>
    <DESCRIPT>abap2UI5 - guide to building apps (generated)</DESCRIPT>
    <STATE>1</STATE>
    <CLSCCINCL>X</CLSCCINCL>
    <FIXPT>X</FIXPT>
    <UNICODE>X</UNICODE>
   </VSEOCLASS>
  </asx:values>
 </asx:abap>
</abapGit>
`;

function main() {
  const wanted = {
    [ABAP]: guideClass(fs.readFileSync(path.join(ROOT, SOURCE), "utf8")),
    [XML]: XML_TEXT,
  };
  const stale = [];
  for (const [rel, text] of Object.entries(wanted)) {
    const file = path.join(ROOT, rel);
    const now = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : undefined;
    if (now === text) continue;
    if (CHECK) stale.push(rel);
    else fs.writeFileSync(file, text);
  }
  if (stale.length > 0) {
    console.log(`Stale - ${SOURCE} and its class disagree:`);
    for (const rel of stale) console.log(`  ${rel}`);
    console.log("");
    console.log("Run 'npm run guide-class' and commit what it wrote. Never edit the class by hand.");
    process.exit(1);
  }
  if (!CHECK) console.log(`${ABAP} written from ${SOURCE}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
